-- {"operators": "CTE,FULL_OUTER_JOIN,AGGREGATE", "complexity": "high", "is_incremental": true, "has_nulls": true, "has_cast": false, "has_case": false, "tables": "ORDER_LINE,HISTORY", "openivm_verified": true}
WITH line_totals AS (SELECT OL_W_ID, OL_D_ID, SUM(OL_AMOUNT) AS line_amount FROM ORDER_LINE GROUP BY OL_W_ID, OL_D_ID), pay_totals AS (SELECT H_W_ID, H_D_ID, SUM(H_AMOUNT) AS pay_amount FROM HISTORY GROUP BY H_W_ID, H_D_ID) SELECT COALESCE(l.OL_W_ID, p.H_W_ID) AS w_id, COALESCE(l.OL_D_ID, p.H_D_ID) AS d_id, l.line_amount, p.pay_amount FROM line_totals l FULL OUTER JOIN pay_totals p ON l.OL_W_ID = p.H_W_ID AND l.OL_D_ID = p.H_D_ID;
